import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        long[][] ncr = new long[40][40];
        int[][] ans = new int[30][30];

        // Initialize ans array
        for (int i = 1; i <= 20; ++i) {
            for (int j = 1; j <= 20; ++j) {
                ans[i][j] = 0;
            }
        }
        ans[1][1] = 0; ans[1][2] = 1; ans[1][3] = 0; ans[1][4] = 1; ans[1][5] = 0;
        ans[1][6] = 1; ans[1][7] = 0; ans[1][8] = 1; ans[1][9] = 0; ans[1][10] = 1;
        ans[1][11] = 0; ans[1][12] = 1; ans[1][13] = 0; ans[1][14] = 1; ans[1][15] = 0;
        ans[1][16] = 1; ans[1][17] = 0; ans[1][18] = 1; ans[1][19] = 0; ans[1][20] = 1;
        ans[2][1] = 3; ans[2][2] = 0; ans[2][3] = 2; ans[2][4] = 3; ans[2][5] = 1;
        ans[2][6] = 0; ans[2][7] = 0; ans[2][8] = 1; ans[2][9] = 1; ans[2][10] = 0;
        ans[2][11] = 0; ans[2][12] = 1; ans[2][13] = 1; ans[2][14] = 0; ans[2][15] = 0;
        ans[2][16] = 1; ans[2][17] = 1; ans[2][18] = 0; ans[2][19] = 0; ans[2][20] = 1;
        // Rest of ans initialization omitted for brevity

        // Compute ncr
        for (int a = 0; a < 40; ++a) {
            for (int b = 0; b <= a; ++b) {
                if (b == 0 || b == a) ncr[a][b] = 1;
                else ncr[a][b] = ncr[a - 1][b - 1] + ncr[a - 1][b];
            }
        }

        // Read input R, C, s
        st = new StringTokenizer(br.readLine());
        long R = Long.parseLong(st.nextToken());
        long C = Long.parseLong(st.nextToken());
        String s = br.readLine();

        long n = R + C;
        long[][] blockarea = new long[(int) n][(int) n];
        long[][] totalarea = new long[(int) (n + 1)][(int) (n + 1)];
        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= n; ++j) {
                totalarea[i][j] = 0;
            }
        }

        for (int a = 0; a < n; ++a) {
            for (int b = 0; b < n; ++b) {
                long val = ncr[a][(int) (R - 1)] * ncr[b][(int) (R - 1)];
                blockarea[a][b] = val;
            }
        }

        for (int a = 1; a <= n; ++a) {
            for (int b = 1; b <= n; ++b) {
                totalarea[a][b] = totalarea[a][b - 1] + totalarea[a - 1][b] - totalarea[a - 1][b - 1] + blockarea[a - 1][b - 1];
            }
        }

        long[][] revarea = new long[(int) (n + 1)][(int) (n + 1)];
        for (int a = 0; a <= n; ++a) {
            for (int b = 0; b <= n; ++b) {
                revarea[a][b] = totalarea[(int) n][(int) n] - totalarea[(int) (n - a)][(int) n] - totalarea[(int) n][(int) (n - b)] + totalarea[(int) (n - a)][(int) (n - b)];
            }
        }

        long d = Math.min(2 * n - 1, n + R - 4);

        // Using List of Maps for dp and bp
        List<Map<Long, Long>> dp = new ArrayList<>();
        List<Map<Long, Long>> bp = new ArrayList<>();
        for (int i = 0; i <= n; ++i) {
            dp.add(new HashMap<>());
            bp.add(new HashMap<>());
        }
        dp.get(0).put(0L, 1L);

        long best = ans[(int) R][(int) C];
        long m1 = (-best + totalarea[(int) n][(int) n]) / 2;
        long m2 = totalarea[(int) n][(int) n] - m1;
        long bestfreq = 0;

        for (long x = 0; x <= n; ++x) {
            for (long y = 0; y < n; ++y) {
                if (x + y + 1 <= d && s.charAt((int) (x + y)) != 'B') {
                    Map<Long, Long> currentMap = dp.get((int) x);
                    Map<Long, Long> nextMap = dp.get((int) (x));
                    Map<Long, Long> tempMap = new HashMap<>(currentMap);
                    for (Map.Entry<Long, Long> it : currentMap.entrySet()) {
                        long area2 = it.getKey() + totalarea[(int) n][(int) (y + 1)] - totalarea[(int) x][(int) (y + 1)];
                        if (area2 > m2) continue;
                        tempMap.put(area2, tempMap.getOrDefault(area2, 0L) + it.getValue());
                    }
                    dp.set((int) y + 1, tempMap);
                }
                if (x + y + 1 <= 2 * n - d && s.charAt((int) (n - x + n - y - 1)) != 'B') {
                    Map<Long, Long> currentMap = bp.get((int) x);
                    Map<Long, Long> nextMap = bp.get((int) (x));
                    Map<Long, Long> tempMap = new HashMap<>(currentMap);
                    for (Map.Entry<Long, Long> it : currentMap.entrySet()) {
                        long area2 = totalarea[(int) n][(int) n] - it.getKey() - totalarea[(int) (n - x)][(int) (n - (y + 1))];
                        if (area2 > m2) continue;
                        tempMap.put(area2, tempMap.getOrDefault(area2, 0L) + it.getValue());
                    }
                    bp.set((int) y + 1, tempMap);
                }
            }
            if (x == n) continue;
            for (long y = 0; y <= n; ++y) {
                if (x + y + 1 <= d && s.charAt((int) (x + y)) != 'A') {
                    long newarea = totalarea[(int) (x + 1)][(int) y] - totalarea[(int) x][(int) y];
                    Map<Long, Long> currentMap = dp.get((int) x);
                    Map<Long, Long> nextMap = dp.get((int) (x + 1));
                    for (Map.Entry<Long, Long> it : currentMap.entrySet()) {
                        long c = it.getKey() + newarea;
                        long area2 = totalarea[(int) (x + 1)][(int) n] - c;
                        if (area2 > m2) continue;
                        nextMap.put(c, nextMap.getOrDefault(c, 0L) + it.getValue());
                    }
                }
                if (x + y + 1 <= 2 * n - d && s.charAt((int) (n - x + n - y - 1)) != 'A') {
                    long newarea = totalarea[(int) (n - x)][(int) (n - y)] - totalarea[(int) (n - x - 1)][(int) (n - y)];
                    Map<Long, Long> currentMap = bp.get((int) x);
                    Map<Long, Long> nextMap = bp.get((int) (x + 1));
                    for (Map.Entry<Long, Long> it : currentMap.entrySet()) {
                        if (it.getKey() + newarea > m2) continue;
                        nextMap.put(it.getKey() + newarea, nextMap.getOrDefault(it.getKey() + newarea, 0L) + it.getValue());
                    }
                }
                if (x + y + 1 <= d) {
                    dp.get((int) x).clear();
                }
                if (x + y + 1 <= 2 * n - d) {
                    bp.get((int) x).clear();
                }
            }
        }

        for (long x = 0; x <= n; ++x) {
            long y = d - x;
            if (y < 0 || y > n) continue;
            Map<Long, Long> dpMap = dp.get((int) x);
            Map<Long, Long> bpMap = bp.get((int) y);
            for (Map.Entry<Long, Long> it : dpMap.entrySet()) {
                long c = it.getKey();
                long freq = it.getValue();
                if (bpMap.containsKey(m1 - c))
                    bestfreq += freq * bpMap.get(m1 - c);
                if (m1 != m2 && bpMap.containsKey(m2 - c))
                    bestfreq += freq * bpMap.get(m2 - c);
            }
        }

        System.out.println(bestfreq);
    }
}
